["assertThatThrownBy(()->transactions.mutate(first,context->{
            assertThat(versions.lockSignedProgress(context)).isTrue();versions.markSignedProgress(context);goals.signedProgress(context,id,-3000L);
            throw new IllegalStateException("synthetischer Fehler nach Teilzugriff");
        })).isInstanceOf(IllegalStateException.class)", "assertThat(versions.lockSignedProgress(context)).isTrue()", "assertThat(application.allGoals(first).getFirst().progressCents()).isZero()", "assertThat(marked()).isFalse()", "assertThatThrownBy(()->application.progressGoalV2(first,id,-3000L)).isInstanceOf(RuntimeException.class)"]

["assertThatThrownBy(() -> transactions.mutate(UUID.randomUUID(), context -> {
                state.markSignedProgress(context);
                state.markMonthlyEffect(context);
                throw new IllegalStateException("Abbruch vor Commit");
            })).hasMessage("Abbruch vor Commit")", "assertThat(db.admin.queryForObject("SELECT signed_progress_used OR monthly_effects_used FROM api_version.state", Boolean.class)).isFalse()", "assertThatThrownBy(() -> transactions.read(UUID.randomUUID(), context -> { state.markSignedProgress(context); return null; }))
                .isInstanceOf(IllegalStateException.class)", "assertThat(db.admin.queryForObject("SELECT signed_progress_used AND monthly_effects_used FROM api_version.state", Boolean.class)).isTrue()", "assertThatThrownBy(() -> db.admin.execute("UPDATE api_version.state SET signed_progress_used=false")).hasMessageContaining("dauerhaft")", "assertThatThrownBy(() -> db.admin.execute("SELECT api_version.set_retirement(false,gen_random_uuid(),repeat('b',64),repeat('b',64),repeat('b',64))"))
                .hasMessageContaining("Rücknahme")", "assertThatThrownBy(() -> new ApiVersionState(db.runtime, "compatible", "", "")).isInstanceOf(IllegalStateException.class)", "assertThatThrownBy(() -> new ApiVersionState(db.runtime, "retired", "b".repeat(64), UUID.randomUUID().toString()))
                .isInstanceOf(IllegalStateException.class)"]

["assertThat(denied.code).as(denied.output).isNotZero()", "assertThat(denied.output).contains(switch(failure) {
